import java.util.ArrayList;
import java.util.List;

public class Main {
    record Book(String id, String title, String borrower) {}

    public static void main(String[] args) {
        Book book = new Book("B001", "Java Basics", "");
        List<Book> before = List.of(book);
        List<Book> after = new ArrayList<>(before);
        after.set(0, new Book(book.id(), book.title(), "Mona"));
        System.out.println(before.get(0).borrower().isEmpty());
        System.out.println(after.get(0).borrower());
    }
}
